INSERT INTO public.grammar_patterns (pattern, level, meaning, structure, examples, tags) VALUES
('-아서/어서','L1','because (cause/reason, joined to verb stem)','V-아서/어서 + result clause','[{"ko":"비가 와서 우산을 가져왔어요.","en":"It was raining, so I brought an umbrella."},{"ko":"피곤해서 일찍 잤어요.","en":"I was tired, so I slept early."}]'::jsonb,'{cause,connective}'),
('-(으)니까','L2','because/since (speaker-centered reason)','V-(으)니까 + clause','[{"ko":"시간이 없으니까 빨리 가요.","en":"Since there''s no time, let''s hurry."},{"ko":"맛있으니까 더 먹어요.","en":"It''s delicious, so eat more."}]'::jsonb,'{cause,connective}'),
('-(으)면','L1','if / when','V-(으)면 + clause','[{"ko":"비가 오면 안 갈 거예요.","en":"If it rains, I won''t go."},{"ko":"심심하면 전화해요.","en":"Call me if you''re bored."}]'::jsonb,'{conditional}'),
('-고 있다','L1','progressive (be ~ing)','V-고 있다','[{"ko":"지금 책을 읽고 있어요.","en":"I''m reading a book now."},{"ko":"동생이 자고 있어요.","en":"My sibling is sleeping."}]'::jsonb,'{tense,aspect}'),
('-았/었어요','L1','past polite','V-았/었어요','[{"ko":"어제 영화를 봤어요.","en":"I watched a movie yesterday."},{"ko":"밥을 먹었어요.","en":"I ate."}]'::jsonb,'{tense}'),
('-(으)ㄹ 거예요','L1','will / probably','V-(으)ㄹ 거예요','[{"ko":"내일 갈 거예요.","en":"I''ll go tomorrow."},{"ko":"비가 올 거예요.","en":"It will probably rain."}]'::jsonb,'{future,tense}'),
('-(으)러','L1','in order to (with go/come)','V-(으)러 가다/오다','[{"ko":"밥을 먹으러 가요.","en":"I''m going to eat."},{"ko":"친구를 만나러 왔어요.","en":"I came to meet a friend."}]'::jsonb,'{purpose}'),
('-(으)려고','L2','intending to','V-(으)려고 + clause','[{"ko":"공부하려고 도서관에 갔어요.","en":"I went to the library to study."},{"ko":"사진을 찍으려고 카메라를 샀어요.","en":"I bought a camera to take pictures."}]'::jsonb,'{purpose,intention}'),
('-아/어 주세요','L1','please do (for me)','V-아/어 주세요','[{"ko":"천천히 말해 주세요.","en":"Please speak slowly."},{"ko":"도와주세요.","en":"Please help me."}]'::jsonb,'{request,polite}'),
('-(으)ㄹ 수 있다/없다','L1','can / cannot','V-(으)ㄹ 수 있다','[{"ko":"한국어를 할 수 있어요.","en":"I can speak Korean."},{"ko":"매운 거 못 먹어요.","en":"I can''t eat spicy food."}]'::jsonb,'{ability}'),
('-아/어도 되다','L2','it''s ok to / may','V-아/어도 되다','[{"ko":"여기 앉아도 돼요?","en":"May I sit here?"},{"ko":"이거 먹어도 돼요.","en":"You may eat this."}]'::jsonb,'{permission}'),
('-(으)면 안 되다','L2','must not','V-(으)면 안 되다','[{"ko":"여기서 사진 찍으면 안 돼요.","en":"You must not take photos here."}]'::jsonb,'{prohibition}'),
('-아야/어야 하다','L2','have to / must','V-아야/어야 하다','[{"ko":"내일 일찍 일어나야 해요.","en":"I have to get up early tomorrow."}]'::jsonb,'{obligation}'),
('-는/(으)ㄴ 것 같다','L2','it seems / I think','V-는 것 같다','[{"ko":"비가 오는 것 같아요.","en":"It seems to be raining."},{"ko":"맛있는 것 같아요.","en":"I think it''s delicious."}]'::jsonb,'{guess}'),
('-(으)ㄴ 적이 있다','L2','have done before (experience)','V-(으)ㄴ 적이 있다','[{"ko":"한국에 가 본 적이 있어요.","en":"I''ve been to Korea before."}]'::jsonb,'{experience}'),
('-기 전에','L1','before doing','V-기 전에','[{"ko":"자기 전에 이를 닦아요.","en":"I brush my teeth before sleeping."}]'::jsonb,'{time,sequence}'),
('-(으)ㄴ 후에','L1','after doing','V-(으)ㄴ 후에','[{"ko":"수업이 끝난 후에 만나요.","en":"Let''s meet after class ends."}]'::jsonb,'{time,sequence}'),
('-(으)면서','L2','while doing (simultaneously)','V-(으)면서','[{"ko":"음악을 들으면서 공부해요.","en":"I study while listening to music."}]'::jsonb,'{time,simultaneous}'),
('-(으)니까 (discovery)','L3','discovered that (upon doing)','V-(으)니까 + discovery','[{"ko":"문을 여니까 비가 오고 있었어요.","en":"When I opened the door, it was raining."}]'::jsonb,'{discovery}'),
('-(으)ㄴ/는데','L2','background / contrast (and, but)','V-(으)ㄴ/는데','[{"ko":"오늘은 바쁜데 내일은 시간 있어요.","en":"I''m busy today but free tomorrow."}]'::jsonb,'{connective,contrast}'),
('-거나','L2','or (between clauses)','V-거나','[{"ko":"주말에 책을 읽거나 영화를 봐요.","en":"On weekends I read or watch movies."}]'::jsonb,'{connective,alternative}'),
('-지만','L1','but','V-지만','[{"ko":"비싸지만 맛있어요.","en":"It''s expensive but delicious."}]'::jsonb,'{contrast}'),
('-기 때문에','L2','because of (reason, formal)','V-기 때문에','[{"ko":"바쁘기 때문에 갈 수 없어요.","en":"Because I''m busy, I can''t go."}]'::jsonb,'{cause,formal}'),
('-답니다/-답시다','L3','reported speech / suggestion','V-답니다','[{"ko":"같이 가자고 하답니다.","en":"They say let''s go together."}]'::jsonb,'{reported}'),
('-다고 하다','L3','reported speech (someone said)','V-다고 하다','[{"ko":"비가 온다고 했어요.","en":"They said it''s raining."},{"ko":"내일 만나자고 했어요.","en":"They said let''s meet tomorrow."}]'::jsonb,'{reported}'),
('-자마자','L3','as soon as','V-자마자','[{"ko":"집에 오자마자 잤어요.","en":"As soon as I got home, I slept."}]'::jsonb,'{time}'),
