
-- Expand Hanja dataset
ON CONFLICT DO NOTHING;

-- Grammar patterns reference table
CREATE TABLE IF NOT EXISTS public.grammar_patterns (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  pattern text NOT NULL UNIQUE,
  level text NOT NULL DEFAULT 'L2',
  meaning text NOT NULL,
  structure text,
  examples jsonb NOT NULL DEFAULT '[]'::jsonb,
  tags text[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.grammar_patterns TO anon, authenticated;
GRANT ALL ON public.grammar_patterns TO service_role;
ALTER TABLE public.grammar_patterns ENABLE ROW LEVEL SECURITY;
CREATE POLICY "grammar_patterns_public_read" ON public.grammar_patterns FOR SELECT TO anon, authenticated USING (true);

ON CONFLICT (pattern) DO NOTHING;
